document.addEventListener("DOMContentLoaded",function(){var t=document.querySelectorAll(".language-switcher");Array.prototype.forEach.call(t,function(t){t.addEventListener("click",function(t){t.stopPropagation(),this.classList.contains("active")?this.classList.remove("active"):this.classList.add("active")})}),document.addEventListener("click",function(e){Array.prototype.forEach.call(t,function(t){t.contains(e.target)||t.classList.remove("active")})});var e=document.querySelectorAll(".language-switcher .option");Array.prototype.forEach.call(e,function(t){t.addEventListener("click",function(e){e.stopPropagation();var a=t.getAttribute("data-value");if(e.isTrusted){const t=new URLSearchParams(window.location.search);t.set("lang",a),window.location.search=t.toString()}})})});